class Base {
    public:
        virtual void virtualFunc();  // Declares a virtual function; compiler adds an entry in the vtable
        int dataMember;  // Non-virtual member; follows the vpointer in memory layout
};

class Derived : public Base {
    public:
        void virtualFunc() override;  // Overrides the virtual function; updates the vtable entry for this class
};

// Implementation notes: The 'virtual' keyword triggers vtable generation. For an object of type Derived, memory layout is approximately: [vpointer (points to Derived's vtable)] [dataMember] [other members]. The vtable for Derived contains pointers to Derived::virtualFunc and Base's other virtual functions if any.
